.screen {
  position: absolute; inset: 0;
  display: flex; flex-direction: column;
  align-items: center; justify-content: center;
  background: radial-gradient(ellipse at center, rgba(2, 6, 14, 0.25) 0%, rgba(1, 3, 8, 0.78) 100%);
  animation: screen-in 0.5s ease both;
}
@keyframes screen-in { from { opacity: 0; } to { opacity: 1; } }

.title {
  font-size: clamp(44px, 7vw, 88px);
  font-weight: 200;
  letter-spacing: 0.34em;
  text-indent: 0.34em;
  color: #fff;
  text-shadow: 0 0 18px var(--accent), 0 0 60px rgba(39, 232, 255, 0.55);
  animation: title-flicker 4s ease-in-out both;
}
@keyframes title-flicker {
  0% { opacity: 0; filter: blur(6px); }
  8% { opacity: 0.7; filter: blur(1px); }
  11% { opacity: 0.2; }
  15% { opacity: 1; filter: blur(0); }
  100% { opacity: 1; }
}

.subtitle {
  margin: 14px 0 52px;
  font-size: 15px;
  letter-spacing: 0.6em;
  text-indent: 0.6em;
  text-transform: uppercase;
  color: var(--accent);
  opacity: 0.8;
}

.screen h2 {
  font-weight: 300;
  letter-spacing: 0.5em;
  text-indent: 0.5em;
  text-transform: uppercase;
  margin-bottom: 26px;
  color: var(--accent);
}

.briefing { max-width: 680px; }
.briefing p {
  margin: 14px 0;
  line-height: 1.65;
  font-size: 15.5px;
  color: var(--text);
  opacity: 0;
  animation: brief-line 0.8s ease forwards;
}
.briefing p:nth-child(2) { animation-delay: 0.5s; }
.briefing p:nth-child(3) { animation-delay: 1.4s; }
.briefing p:nth-child(4) { animation-delay: 2.3s; }
.briefing p:nth-child(5) { animation-delay: 3.2s; }
@keyframes brief-line { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: none; } }

.controls-table { border-collapse: collapse; font-size: 14.5px; }
.controls-table td { padding: 7px 22px; letter-spacing: 0.08em; }
.controls-table td:first-child {
  color: var(--accent);
  text-align: right;
  font-weight: 600;
  letter-spacing: 0.15em;
}

.menu-footer {
  position: absolute; bottom: 26px;
  font-size: 11.5px; letter-spacing: 0.3em; text-transform: uppercase;
  opacity: 0.45;
}

.gameover-title {
  font-size: clamp(38px, 6vw, 70px);
  font-weight: 200;
  letter-spacing: 0.3em; text-indent: 0.3em;
  color: var(--danger);
  text-shadow: 0 0 24px rgba(255, 59, 48, 0.7);
  animation: title-flicker 2.2s ease both;
}
.gameover-epitaph { margin: 22px 0 8px; font-style: italic; opacity: 0.75; max-width: 560px; text-align: center; line-height: 1.6; }
.gameover-stats { margin: 20px 0 10px; font-size: 17px; letter-spacing: 0.28em; text-transform: uppercase; color: var(--text); }
.gameover-stats b { color: var(--warn); font-weight: 600; }
.gameover-credits { margin: 0 0 36px; font-size: 13px; letter-spacing: 0.24em; text-transform: uppercase; color: #8aff9f; opacity: 0.9; }
.gameover-credits b { font-weight: 600; }

.legacy-panel { min-width: 620px; display: flex; flex-direction: column; gap: 12px; }
.legacy-credits { font-size: 12.5px; letter-spacing: 0.16em; text-transform: uppercase; color: #8aff9f; margin-bottom: 8px; }
.legacy-credits b { font-size: 16px; }
