.crosshair {
  position: absolute; left: 50%; top: 50%;
  width: 26px; height: 26px;
  transform: translate(-50%, -50%);
}
/* Layered reticle: broken arc ring around the cross. */
.crosshair-ring {
  position: absolute; left: 50%; top: 50%;
  width: 46px; height: 46px;
  transform: translate(-50%, -50%) rotate(45deg);
  border: 1px solid rgba(39, 232, 255, 0.55);
  border-radius: 50%;
  clip-path: polygon(0 0, 38% 0, 38% 38%, 0 38%, 0 100%, 38% 100%, 38% 62%, 100% 62%, 100% 100%, 62% 100%, 62% 0, 100% 0, 100% 38%, 62% 38%);
  box-shadow: 0 0 8px rgba(39, 232, 255, 0.25), inset 0 0 8px rgba(39, 232, 255, 0.15);
}

/* Center cluster: shield/hull semicircle arcs under the reticle, boost arc
   above (boost only), seeker reload chip below. */
.center-arcs {
  position: absolute; left: 50%; top: 50%;
  width: 210px; height: 210px;
  transform: translate(-50%, -50%);
  pointer-events: none;
  opacity: 0.6;
}
.center-arcs path { fill: none; stroke-width: 2.4; stroke-linecap: round; }
.arc-track { stroke: rgba(255, 255, 255, 0.09); }
.arc-shield {
  stroke: var(--accent);
  stroke-dasharray: 96.3;
  filter: drop-shadow(0 0 3px rgba(39, 232, 255, 0.6));
}
.arc-hull {
  stroke: #35e88a;
  stroke-dasharray: 81.7;
  filter: drop-shadow(0 0 3px rgba(53, 232, 138, 0.5));
}
.arc-boost {
  stroke: #c26aff;
  stroke-dasharray: 96.3;
  filter: drop-shadow(0 0 4px rgba(194, 106, 255, 0.7));
}
.center-seeker {
  position: absolute; left: 50%; top: calc(50% + 116px);
  transform: translateX(-50%);
  width: 92px; height: 17px;
  display: flex; align-items: center; justify-content: center;
  overflow: hidden;
  border: 1px solid rgba(255, 179, 71, 0.3);
  background: rgba(4, 10, 18, 0.4);
  font-size: 10px; letter-spacing: 0.2em; color: var(--warn);
}
.center-seeker i {
  position: absolute; left: 0; top: 0; bottom: 0; width: 0;
  background: rgba(255, 179, 71, 0.22);
}
.center-seeker span { position: relative; }
.missile-warning {
  position: absolute;
  left: 50%;
  top: calc(50% - 152px);
  transform: translate(-50%, -8px) scale(0.96);
  min-width: 230px;
  padding: 8px 18px 7px;
  border: 1px solid rgba(255, 179, 71, 0.75);
  background: rgba(18, 7, 3, 0.88);
  box-shadow: 0 0 22px rgba(255, 111, 32, 0.28), inset 0 0 18px rgba(255, 111, 32, 0.08);
  color: #ffc06a;
  text-align: center;
  text-transform: uppercase;
  opacity: 0;
  transition: opacity 0.12s ease, transform 0.12s ease;
}
.missile-warning.show { opacity: 1; transform: translate(-50%, 0) scale(1); }
.missile-warning strong {
  display: block;
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.34em;
  text-indent: 0.34em;
  text-shadow: 0 0 12px currentColor;
}
.missile-warning span {
  display: block;
  margin-top: 3px;
  font-size: 10px;
  letter-spacing: 0.24em;
  text-indent: 0.24em;
  opacity: 0.82;
}
.missile-warning.imminent {
  color: #ff4d3d;
  border-color: rgba(255, 48, 36, 0.9);
  background: rgba(28, 2, 3, 0.92);
  animation: missile-danger 0.36s ease-in-out infinite alternate;
}
@keyframes missile-danger {
  from { box-shadow: 0 0 14px rgba(255, 36, 28, 0.3), inset 0 0 12px rgba(255, 36, 28, 0.08); }
  to { box-shadow: 0 0 34px rgba(255, 36, 28, 0.72), inset 0 0 24px rgba(255, 36, 28, 0.22); }
}
.crosshair::before, .crosshair::after {
  content: ''; position: absolute; background: var(--accent);
  box-shadow: 0 0 6px var(--accent);
}
.crosshair::before { left: 50%; top: 0; width: 1.5px; height: 100%; transform: translateX(-50%); clip-path: polygon(0 0, 100% 0, 100% 32%, 0 32%, 0 68%, 100% 68%, 100% 100%, 0 100%); }
.crosshair::after { top: 50%; left: 0; height: 1.5px; width: 100%; transform: translateY(-50%); clip-path: polygon(0 0, 32% 0, 32% 100%, 0 100%, 68% 0, 100% 0, 100% 100%, 68% 100%); }

.hitmarker {
  position: absolute; left: 50%; top: 50%;
  width: 34px; height: 34px;
  transform: translate(-50%, -50%) rotate(45deg);
  opacity: 0;
  pointer-events: none;
}
.hitmarker::before, .hitmarker::after {
  content: ''; position: absolute; background: #fff;
}
.hitmarker::before { left: 50%; top: 0; width: 2px; height: 100%; transform: translateX(-50%); clip-path: polygon(0 0, 100% 0, 100% 26%, 0 26%, 0 74%, 100% 74%, 100% 100%, 0 100%); }
.hitmarker::after { top: 50%; left: 0; height: 2px; width: 100%; transform: translateY(-50%); clip-path: polygon(0 0, 26% 0, 26% 100%, 0 100%, 74% 0, 100% 0, 100% 100%, 74% 100%); }
.hitmarker.kill::before, .hitmarker.kill::after { background: var(--danger); }
.hitmarker.show { animation: hitmark 0.25s ease-out both; }
@keyframes hitmark {
  0% { opacity: 1; transform: translate(-50%, -50%) rotate(45deg) scale(1.5); }
  100% { opacity: 0; transform: translate(-50%, -50%) rotate(45deg) scale(0.9); }
}
