___CSS_LOADER_EXPORT___.push([module.id, `/* ---------- HUD ---------- */
#hud { position: absolute; inset: 0; opacity: 0; transition: opacity 0.4s ease; }
#hud.visible { opacity: 1; }

.hud-corner { position: absolute; display: flex; flex-direction: column; gap: 6px; }

/* Angular panel plates behind each HUD cluster. */
/* NOTE: no \`position\` here — .hud-corner's absolute placement must win. */
.hud-panel {
  background:
    repeating-linear-gradient(0deg, rgba(39, 232, 255, 0.025) 0 1px, transparent 1px 3px),
    linear-gradient(135deg, rgba(6, 16, 26, 0.78), rgba(4, 10, 18, 0.55));
  border: 1px solid rgba(39, 232, 255, 0.16);
  border-left: 2px solid rgba(39, 232, 255, 0.55);
  box-shadow: 0 0 22px rgba(0, 0, 0, 0.45), inset 0 0 26px rgba(39, 232, 255, 0.04);
  backdrop-filter: blur(3px);
  padding: 12px 16px 11px;
  clip-path: polygon(0 0, calc(100% - 16px) 0, 100% 16px, 100% 100%, 16px 100%, 0 calc(100% - 16px));
}
/* Accent tick along each plate's top edge — cockpit-console flavor. */
.hud-panel::before {
  content: ''; position: absolute; top: 0; left: 10px;
  width: 46px; height: 2px;
  background: linear-gradient(90deg, var(--accent), transparent);
  opacity: 0.8;
}
.panel-title {
  font-size: 9px; letter-spacing: 0.55em; text-transform: uppercase;
  color: var(--accent); opacity: 0.75; margin-bottom: 7px;
  border-bottom: 1px solid rgba(39, 232, 255, 0.18);
  padding-bottom: 4px;
}
.bar::after {
  content: ''; position: absolute; inset: 0; pointer-events: none;
  background: repeating-linear-gradient(90deg, transparent 0 13px, rgba(2, 6, 10, 0.6) 13px 15px);
}
.missile-status {
  position: relative; overflow: hidden;
  padding: 2px 6px;
  border: 1px solid rgba(255, 179, 71, 0.25);
}
.missile-fill {
  position: absolute; left: 0; top: 0; bottom: 0; width: 0;
  background: rgba(255, 179, 71, 0.22);
}
.missile-status span { position: relative; }
.speed-row { display: flex; align-items: baseline; gap: 8px; margin-bottom: 8px; }
.speed-row .speed-value { font-size: 27px; font-weight: 200; letter-spacing: 0.1em; color: #fff; text-shadow: 0 0 12px var(--accent-dim); }
.speed-row .speed-unit { font-size: 9.5px; letter-spacing: 0.35em; text-transform: uppercase; opacity: 0.6; }
.speed-row .boost-tag { margin-left: auto; }
